-- ============================================
-- LUMA — Thème 13 : MOYEN 3/3 x4 — Proposer une collaboration
-- ============================================


update scenarios set content = '{"characters": {"contact": "votre contact"}, "start_node": "n1", "nodes": {"n1": {"speaker": "contact", "text": "Your work sounds fascinating. I hadn''t thought about the industry from that angle before.", "text_fr": "Votre travail semble fascinant. J''avais pas pensé à l''industrie sous cet angle avant.", "choices": [{"text": "Actually, I think our work might complement each other quite well.", "text_fr": "En fait, je pense que nos travaux pourraient bien se compléter.", "next": "n2"}, {"text": "I''m curious — have you ever considered a project combining both our expertise?", "text_fr": "Je suis curieux — vous avez déjà envisagé un projet combinant nos deux expertises ?", "next": "n2b"}]}, "n2": {"speaker": "contact", "text": "That''s an interesting thought. What did you have in mind specifically?", "text_fr": "C''est une pensée intéressante. Vous aviez quoi en tête spécifiquement ?", "choices": [{"text": "Perhaps a joint workshop combining our different approaches to this problem.", "text_fr": "Peut-être un atelier conjoint combinant nos différentes approches de ce problème.", "next": "n3"}]}, "n2b": {"speaker": "contact", "text": "Actually, no, but now that you mention it, that could be really valuable.", "text_fr": "En fait, non, mais maintenant que vous le mentionnez, ça pourrait être vraiment précieux.", "choices": [{"text": "I was thinking something like a joint workshop or webinar series.", "text_fr": "Je pensais à quelque chose comme un atelier conjoint ou une série de webinaires.", "next": "n3"}]}, "n3": {"speaker": "contact", "text": "I like that idea. What would each of us bring to something like that?", "text_fr": "J''aime cette idée. Qu''est-ce que chacun de nous apporterait à quelque chose comme ça ?", "choices": [{"text": "I''d bring the technical side, while your marketing expertise could shape the outreach.", "text_fr": "J''apporterais le côté technique, pendant que votre expertise marketing pourrait façonner la diffusion.", "next": "n4"}]}, "n4": {"speaker": "contact", "text": "That actually makes a lot of sense — our skill sets really do complement each other.", "text_fr": "Ça a en fait beaucoup de sens — nos compétences se complètent vraiment.", "choices": [{"text": "Would you be open to discussing this further after the conference?", "text_fr": "Vous seriez ouvert à discuter de ça plus après la conférence ?", "next": "n5"}, {"text": "I don''t want to be too forward, but I''d genuinely love to explore this properly.", "text_fr": "Je veux pas être trop direct, mais j''aimerais vraiment explorer ça correctement.", "next": "n5"}]}, "n5": {"speaker": "contact", "text": "Not forward at all — I''d genuinely welcome that conversation. Let''s set something up.", "text_fr": "Pas du tout direct — j''accueillerais vraiment cette conversation. Organisons quelque chose.", "choices": [{"text": "Great, I''ll follow up next week with some initial ideas.", "text_fr": "Super, je vais relancer la semaine prochaine avec quelques idées initiales.", "next": "n6"}]}, "n6": {"speaker": "contact", "text": "Perfect, I''m looking forward to seeing what we can build together.", "text_fr": "Parfait, j''ai hâte de voir ce qu''on peut construire ensemble.", "choices": [{"text": "Me too, this feels like the start of something genuinely promising.", "text_fr": "Moi aussi, ça semble être le début de quelque chose de vraiment prometteur.", "next": "end_proposed"}]}, "end_proposed": {"speaker": "contact", "text": "Agreed. Thank you for having the courage to propose this — glad you did.", "text_fr": "D''accord. Merci d''avoir eu le courage de proposer ça — content que vous l''ayez fait.", "end": true, "ending_label": "Collaboration proposée avec tact et succès 🤝💡"}}}'::jsonb, is_playable = true
where title = 'Proposer une collaboration'
  and theme_id = (select id from scenario_themes where position = 13 and language_id = (select id from languages where code = 'en'));
